class Solution {
public:
    vector<vector<int>> subsetsWithDup(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        set<vector<int>> seen;
        vector<vector<int>> res;
        for (int mask = 0; mask < (1 << n); ++mask) {
            vector<int> cur;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) cur.push_back(nums[i]);
            }
            if (!seen.count(cur)) {
                seen.insert(cur);
                res.push_back(cur);
            }
        }
        return res;
    }
};

