        res = [[]]
        prevSize = 0
        for i in range(len(nums)):
            size = len(res)
            start = prevSize if i > 0 and nums[i] == nums[i - 1] else 0
            prevSize = size
            for j in range(start, size):
                res.append(res[j] + [nums[i]])
